// Set a field
await products.updateOne(
  { name: "Laptop" },
  { $set: { price: 899 } }
);

// Increment a counter
await products.updateOne(
  { _id: id },
  { $inc: { views: 1 } }
);

// Upsert: insert if not found
await products.updateOne(
  { sku: "ABC123" },
  { $set: { name: "Widget", price: 10 } },
  { upsert: true }
);
